-- Installs movie/cinematic skip hooks, respecting addon settings, modifiers and Dontskipvid.
-- Delayed skips recheck preferences before touching the cinematic.

local function ShouldSkipCutscene(step)
    if IsModifierKeyDown() then
        return false
    end
    local profile = APR:GetSettingsProfile()
    if not profile or not profile.enableAddon or not profile.autoSkipCutScene then
        return false
    end
    if step and step.Dontskipvid then
        return false
    end
    return true
end--[[APR_DIAG]]; ShouldSkipCutscene = APRTrace("APR-Core/features/player/Cutscenes.lua:9:ShouldSkipCutscene#1", ShouldSkipCutscene)--[[/APR_DIAG]]

local function CancelCurrentMovie(step)
    if not ShouldSkipCutscene(step) then
        return
    end

    -- Defer past Blizzard's setup; recheck settings in case the addon was disabled.
    C_Timer.After(0, --[[APR_DIAG]]APRTrace("APR-Core/features/player/Cutscenes.lua:29:callback#3", --[[/APR_DIAG]]function()
        if ShouldSkipCutscene(APR:GetCurrentStep()) then
            CinematicFinished(Enum.CinematicType.GameMovie, true, false)
        end
    end--[[APR_DIAG]])--[[/APR_DIAG]])
end--[[APR_DIAG]]; CancelCurrentMovie = APRTrace("APR-Core/features/player/Cutscenes.lua:23:CancelCurrentMovie#2", CancelCurrentMovie)--[[/APR_DIAG]]

hooksecurefunc("MovieFrame_PlayMovie", --[[APR_DIAG]]APRTrace("APR-Core/features/player/Cutscenes.lua:36:callback#4", --[[/APR_DIAG]]function(...)
    local step = APR:GetCurrentStep()
    CancelCurrentMovie(step)
end--[[APR_DIAG]])--[[/APR_DIAG]])

CinematicFrame:HookScript("OnKeyDown", --[[APR_DIAG]]APRTrace("APR-Core/features/player/Cutscenes.lua:41:callback#5", --[[/APR_DIAG]]function(self, key)
    if key == "ESCAPE" then
        if CinematicFrame:IsShown() and CinematicFrame.closeDialog and CinematicFrameCloseDialogConfirmButton then
            CinematicFrameCloseDialog:Hide()
        end
    end
end--[[APR_DIAG]])--[[/APR_DIAG]])

CinematicFrame:HookScript("OnKeyUp", --[[APR_DIAG]]APRTrace("APR-Core/features/player/Cutscenes.lua:49:callback#6", --[[/APR_DIAG]]function(self, key)
    if key == "SPACE" or key == "ESCAPE" or key == "ENTER" then
        if CinematicFrame:IsShown() and CinematicFrame.closeDialog and CinematicFrameCloseDialogConfirmButton then
            CinematicFrameCloseDialogConfirmButton:Click()
        end
    end
end--[[APR_DIAG]])--[[/APR_DIAG]])

APR.SceneCutterEventFrame = CreateFrame("Frame")
APR.SceneCutterEventFrame:RegisterEvent("CINEMATIC_START")
APR.SceneCutterEventFrame:SetScript("OnEvent", --[[APR_DIAG]]APRTrace("APR-Core/features/player/Cutscenes.lua:59:callback#7", --[[/APR_DIAG]]function(self, event, ...)
    local step = APR:GetCurrentStep()
    if not ShouldSkipCutscene(step) then return end
    C_Timer.After(0.5, --[[APR_DIAG]]APRTrace("APR-Core/features/player/Cutscenes.lua:62:callback#8", --[[/APR_DIAG]]function()
        if ShouldSkipCutscene(APR:GetCurrentStep()) then CinematicFrame_CancelCinematic() end
    end--[[APR_DIAG]])--[[/APR_DIAG]])
end--[[APR_DIAG]])--[[/APR_DIAG]])
